// Vendored workflow engine: generated by scripts/sync-workflow-engine.mjs, never edited by hand. Source, commit and local patches: lib/workflow-engine/UPSTREAM.json
/**
 * Mermaid rendering of a workflow definition.
 *
 * The picture of a workflow belongs to the workflow, not to any one run of it.
 * Rendering it per-task produced a diagram of one instance — this owner, this
 * due date, this current step — while claiming to show the organization's
 * process. The engine holds the only complete description of the process (the
 * DSL), so it renders the diagram once at registration and stores the string
 * on the workflow record. Readers render that string; nobody rebuilds a graph.
 *
 * The conditions are baked into the string rather than shipped alongside it:
 * a node carries who may act and what it gates on, and every edge carries the
 * state change that triggers it. A rejection is a labelled dotted edge back to
 * the step it returns to, which is precisely what a linkage-only picture got
 * wrong — a rejection never follows the straight line such a diagram draws.
 */
import type { WorkflowDSL } from '../../../dsl/types.ts';

/** Mermaid node text is quoted; the quote and the escapes it sits inside are
 * the only characters that can break the line. `<br/>` is intentional markup,
 * so text is escaped before any is added. */
function nodeText(value: string): string {
  return value
    .replace(/\\/g, '\\\\')
    .replace(/"/g, '&quot;')
    .replace(/[\r\n]+/g, ' ')
    .trim();
}

/** Mermaid ids must be bare identifiers; step ids come from authored DSLs. */
function nodeId(value: string): string {
  const safe = value.replace(/[^A-Za-z0-9_]/g, '_');
  return /^[A-Za-z_]/.test(safe) ? safe : `s_${safe}`;
}

type Internal = {
  scope?: string;
  other_selector?: { id?: string };
  set?: Record<string, unknown>;
};

/** The state a step must reach for a rule to fire, e.g. open → completed. */
function transitionOf(condition: Record<string, unknown> | undefined): {
  before: string;
  after: string;
} | null {
  const state = condition?.['step$state'] as
    | { $delta?: { before?: unknown; after?: unknown } }
    | undefined;
  const delta = state?.$delta;
  if (!delta) return null;
  const before = typeof delta.before === 'string' ? delta.before : '';
  const after = typeof delta.after === 'string' ? delta.after : '';
  if (!after && !before) return null;
  return { before, after };
}

/** Human label for a transition, used on the edge. */
function edgeLabel(before: string, after: string): string {
  if (after === 'completed') return 'approve';
  if (after === 'rejected') return 'reject';
  if (after === 'escalated') return 'escalate';
  if (before === 'completed' && after === 'open') return 'reopen';
  return after || before || 'advance';
}

/** An edge that routes work backwards, or away from the happy path. */
function isExceptionEdge(before: string, after: string): boolean {
  return after === 'rejected' || after === 'escalated' || before === 'completed';
}

/** The role(s) a step's assignee condition restricts it to, if any. */
function assigneeRoles(step: Record<string, unknown>): string[] {
  const assignee = step.assignee as
    | { condition?: { $or?: { query?: Record<string, unknown> } } }
    | undefined;
  const query = assignee?.condition?.$or?.query;
  if (!query) return [];
  const role = query.role;
  if (typeof role === 'string') return [role];
  if (Array.isArray(role)) return role.filter((r): r is string => typeof r === 'string');
  const inClause = (role as { $in?: unknown } | undefined)?.$in;
  if (Array.isArray(inClause)) return inClause.filter((r): r is string => typeof r === 'string');
  return [];
}

/** A rule that puts its target back to sleep (status false) is bookkeeping for
 * a send-back, not a route: drawing it would show work flowing into a step
 * that is being switched off. */
function deactivates(internal: Internal): boolean {
  const status = internal.set?.status as { value?: unknown } | undefined;
  return status?.value === false;
}

function isRequired(value: unknown): boolean {
  return (value as { default?: unknown } | undefined)?.default === true;
}

/** The condition lines shown inside a step's node. */
export function stepConditions(step: Record<string, unknown>): string[] {
  const lines: string[] = [];

  const roles = assigneeRoles(step);
  const limit = (step.assignee as { limit?: unknown } | undefined)?.limit;
  if (roles.length) {
    lines.push(`👤 ${roles.join(' / ')}`);
  }
  if (typeof limit === 'number' && limit > 0) {
    lines.push(`🔒 ${limit} assignee${limit === 1 ? '' : 's'} max`);
  }
  if (isRequired(step.evidence_required)) lines.push('📎 evidence required');
  if (isRequired(step.comments_required)) lines.push('💬 comment required');
  if (step.ai_review === true) lines.push('🤖 AI review');

  const days = (step.due_on as { $delta?: { days?: unknown } } | undefined)?.$delta?.days;
  if (typeof days === 'number') lines.push(`⏱ due +${days}d`);

  return lines;
}

/**
 * Render the workflow as a mermaid `flowchart LR`.
 *
 * Deterministic: the same DSL always produces byte-identical output, so a
 * stored diagram can be compared against a freshly rendered one to tell
 * whether a definition actually changed.
 */
export function renderWorkflowMermaid(dsl: WorkflowDSL): string {
  const init = dsl?.init as unknown as
    | {
        start_id?: string;
        flatten_order?: string[];
        steps?: Array<Record<string, unknown>>;
        terminal_when?: { selector?: { id?: string } };
      }
    | undefined;
  const steps = init?.steps ?? [];
  if (!steps.length) return '';

  const byId = new Map<string, Record<string, unknown>>();
  for (const step of steps) {
    if (typeof step.id === 'string') byId.set(step.id, step);
  }

  // flatten_order is the authored sequence; steps it omits still get drawn so
  // the diagram never silently hides part of the process.
  const ordered: string[] = [];
  for (const id of init?.flatten_order ?? []) {
    if (byId.has(id) && !ordered.includes(id)) ordered.push(id);
  }
  for (const step of steps) {
    if (typeof step.id === 'string' && !ordered.includes(step.id)) ordered.push(step.id);
  }

  const lines: string[] = ['flowchart LR'];
  const startId = init?.start_id && byId.has(init.start_id) ? init.start_id : ordered[0];
  if (startId) lines.push(`  START((start)) --> ${nodeId(startId)}`);

  for (const id of ordered) {
    const step = byId.get(id)!;
    const title = nodeText(typeof step.title === 'string' ? step.title : id);
    const conditions = stepConditions(step).map(nodeText);
    const body = [title, ...conditions].join('<br/>');
    lines.push(`  ${nodeId(id)}["${body}"]`);
  }

  // Routing lives in the diff rules: a rule whose condition is a state change
  // on one step and whose action opens another step *is* the edge.
  const edges: string[] = [];
  const seen = new Set<string>();
  for (const rule of dsl?.diff ?? []) {
    const internal = (rule as { action?: { internal?: Internal } }).action?.internal;
    if (!internal || internal.scope !== 'other' || deactivates(internal)) continue;
    const target = internal.other_selector?.id;
    const source = (rule as { selector?: { group_selector?: { id?: string } } }).selector
      ?.group_selector?.id;
    if (!source || !target || !byId.has(source) || !byId.has(target)) continue;

    const transition = transitionOf((rule as { condition?: Record<string, unknown> }).condition);
    if (!transition) continue;

    const label = edgeLabel(transition.before, transition.after);
    const arrow = isExceptionEdge(transition.before, transition.after) ? '-.->' : '-->';
    const edge = `  ${nodeId(source)} ${arrow}|"${nodeText(label)}"| ${nodeId(target)}`;
    if (seen.has(edge)) continue;
    seen.add(edge);
    edges.push(edge);
  }
  // A card without routing rules (the gateway sequences its steps itself)
  // would draw every step as an island. Fall back to the authored order for
  // any step no rule leads into, so the sequence is visible either way.
  const ledInto = new Set<string>();
  for (const rule of dsl?.diff ?? []) {
    const internal = (rule as { action?: { internal?: Internal } }).action?.internal;
    // Only a forward rule replaces the fallback edge; a send-back into a step
    // must not hide the normal arrow into it.
    const delta = (rule as { condition?: { 'step$state'?: { $delta?: { before?: string; after?: string } } } })
      .condition?.['step$state']?.$delta;
    const backward = delta ? isExceptionEdge(delta.before ?? '', delta.after ?? '') : false;
    if (internal?.scope === 'other' && !deactivates(internal) && !backward && internal.other_selector?.id) {
      ledInto.add(internal.other_selector.id);
    }
  }
  for (let i = 1; i < ordered.length; i += 1) {
    if (ledInto.has(ordered[i])) continue;
    const edge = `  ${nodeId(ordered[i - 1])} -->|"then"| ${nodeId(ordered[i])}`;
    if (!seen.has(edge)) {
      seen.add(edge);
      edges.push(edge);
    }
  }
  lines.push(...edges);

  // A finish line over every step has no single id: draw it off the last step.
  const terminalId = init?.terminal_when?.selector?.id ??
    (init?.terminal_when ? ordered[ordered.length - 1] : undefined);
  if (terminalId && byId.has(terminalId)) {
    lines.push(`  ${nodeId(terminalId)} -->|"approve"| COMPLETE((complete))`);
  }

  const stepIds = ordered.map(nodeId).join(',');
  if (stepIds) {
    lines.push('  classDef step fill:#ffffff,stroke:#a3a3a3,color:#171717');
    lines.push('  classDef terminal fill:#ecfdf5,stroke:#10b981,color:#065f46');
    lines.push(`  class ${stepIds} step`);
    if (terminalId && byId.has(terminalId)) lines.push('  class COMPLETE terminal');
  }

  return lines.join('\n');
}
